	["desc.Transmogrifier"] = "Una científica de pelo oscuro y gafas de protección, que sostiene pociones brillantes.",
	["desc.Pawnbroker"] = "Un duende verde encaramado a un montón altísimo de armas, escudos y tesoros.",
	["desc.Conjurer"] = "Un espíritu azul y fantasmal que flota sobre un cofre del tesoro.",
	["scene.title.necrodancer"] = "Ilustración del título: Cadence, con la antorcha en alto y la daga desenvainada, se enfrenta a un fantasma azul pálido con una flecha atravesándole la cabeza en un cementerio oscuro. Sobre ellos, el logotipo del juego entre dos calaveras.",
	["scene.title.amplified"] = "Ilustración del título de Amplified: Nocturna, espada en mano, lucha contra un mago esqueleto con sombrero morado cuyo bastón chisporrotea de rayos.",
	["scene.title.synchrony"] = "Ilustración del título de Synchrony: Klarinetta con su espada larga, Chaunter, el fantasma remendado con su farol verde, y Suzu con su arma de asta, bajo el logotipo de Synchrony.",
	["scene.title.halloween"] = "Ilustración del título de Halloween, Truco o trato: Chaunter, el fantasma remendado con su farol verde, y Cadence con una calabaza tallada en la cabeza, entre calabazas brillantes.",
	["scene.title.christmas"] = "Ilustración navideña del título, Merry Cryptmas: Cadence con un abrigo rojo de Papá Noel y su pala; tras ella, un enorme no muerto de barba blanca con gorro de Papá Noel, fantasmas y una parca encapuchada llenan el cielo nevado.",
	["scene.zone1"] = "La cripta: suelos de tierra oscura apisonada y paredes de barro llenas de raíces, huesos y calaveras, algunas de bloques de piedra. Mientras tienes multiplicador de monedas, el suelo destella en cuadros alternos con cada pulso.",
	["scene.zone2"] = "Suelos de piedra verde musgosa y verde azulada, paredes de tierra cubiertas de hojas y pequeñas setas naranjas, y paredes de adoquines pálidos.",
	["scene.zone3"] = "Esta profundidad está dividida en dos: un lado caliente de roca rojiza con suelos de un naranja incandescente, y un lado frío de roca gris azulada con suelos azules helados.",
	["scene.zone4"] = "Las catacumbas: suelos azul oscuro y paredes de ladrillo morado adornadas con esqueletos, calaveras y estandartes.",
	["scene.zone5"] = "Un laboratorio: suelos morado oscuro con baldosas doradas y cian, y paredes de ladrillo magenta cubiertas de tuberías, cables y maquinaria.",
	["scene.boss"] = "Una arena de jefe: un suelo de piedra oscura y paredes de piedra pálida con calaveras y huesos incrustados.",
	["scene.boss.NECRODANCER"] = "El escenario del NecroDancer: una pista de baile verde flanqueada por altavoces morados gigantes.",
	["cs.intro.1"] = "Noche en un cementerio. Cadence, una joven de pelo rubio, con un pañuelo azul y una túnica roja, trepa entre las lápidas con una antorcha y una pala, y se pone a cavar.",
	["cs.intro.2"] = "Su pala atraviesa el suelo y un humo morado brota a su alrededor.",
	["cs.intro.3"] = "El suelo cede. Cae en la oscuridad entre manos esqueléticas que intentan agarrarla.",
	["cs.intro.4"] = "Se estrella contra el suelo de piedra de una cripta entre huesos y queda inmóvil en un charco de sangre.",
	["cs.intro.5"] = "Una luz morada inunda la sala. Un hechicero no muerto de piel azul, con una larga barba blanca y una capa roja, se cierne sobre ella: el NecroDancer.",
	["cs.intro.6"] = "Con su magia le arranca el corazón del pecho y lo sostiene en alto, sonriendo, mientras brilla.",
	["cs.intro.7"] = "Cadence despierta en el suelo y se levanta con su pala, con un rastro de humo morado saliéndole del pecho.",
	["cs.intro.8"] = "Mira al frente, decidida.",
	["cs.cadence1.1"] = "Una casa de madera iluminada por una vela. La pequeña Cadence se asoma por una puerta.",
	["cs.cadence1.2"] = "Su padre Dorian, con una gorra verde, guarda un mapa y herramientas en un baúl.",
	["cs.cadence1.3"] = "La pequeña Cadence baja la mirada, triste, junto a su tío Eli, un hombre grande de barba roja y sombrero negro.",
	["cs.cadence1.4"] = "Años después, una Cadence adolescente rebusca en el viejo baúl de su padre, con una pala apoyada al lado.",
	["cs.cadence1.5"] = "Saca sus notas y un mapa, sonriendo.",
	["cs.cadence1.6"] = "El tío Eli observa desde la puerta, con el ceño fruncido, mientras Cadence aparta la mirada.",
	["cs.cadence1.7"] = "Cadence agarra el mapa con fuerza, decidida.",
	["cs.cadence2.1"] = "Un funeral en una ladera verde. Dolientes con vestidos oscuros están junto a un ataúd rojo cubierto de flores. La pequeña Cadence canta a su lado.",
	["cs.cadence2.2"] = "Detrás de ella, el tío Eli señala con un dedo acusador a su padre Dorian.",
	["cs.cadence2.3"] = "Desde arriba: Dorian extiende las manos, suplicante, mientras Eli se cierne sobre él.",
	["cs.cadence2.4"] = "Primer plano: Dorian aparta la mirada, tenso; Eli tiene el puño apretado.",
	["cs.cadence2.5"] = "Cadence les da la espalda y posa la mano sobre el ataúd mientras pasan volando pétalos rojos.",
	["cs.cadence3.1"] = "Un pícnic soleado junto a un lago. Una mujer con un pañuelo rojo en la cabeza, Melody, toca un laúd mientras Dorian hace girar en el aire a la pequeña Cadence. Un caballo pasta cerca.",
	["cs.cadence3.2"] = "La pequeña Cadence baila y ríe; sus padres se abrazan detrás de ella.",
	["cs.cadence3.3"] = "Más tarde, Melody yace enferma en la cama con la cabeza vendada y manchas oscuras en el brazo. Dorian le sostiene la mano.",
	["cs.cadence3.4"] = "Dorian se da la vuelta, preocupado, mientras la pequeña Cadence observa desde la puerta.",
	["cs.cadence4.1"] = "Cadence se arrodilla junto a un hombre pálido de pelo largo y rojo con armadura dorada: su padre, Dorian.",
	["cs.cadence4.2"] = "En una sala de la cripta con arcos morados, el NecroDancer abre los brazos, con un laúd dorado en una mano.",
	["cs.cadence4.3"] = "Una llama en su otra mano se convierte en el corazón palpitante de Cadence, y lo alza para provocarla.",
	["cs.cadence4.4"] = "Cadence, con su pala y su daga, está hombro con hombro con Dorian, que empuña un pesado martillo dorado.",
	["cs.cadence5.1"] = "El NecroDancer yace derrotado en el suelo. Dorian, con armadura dorada, sostiene su laúd dorado; detrás de él, Cadence brilla con una luz morada.",
	["cs.cadence5.2"] = "Cadence, pala en mano, mira a su padre mientras él se aleja con el laúd.",
	["cs.cadence5.3"] = "Fuera, bajo una luna verde, Cadence y Dorian salen entre lápidas y raíces retorcidas; Dorian lleva el laúd.",
	["cs.melody0.1"] = "Noche en el cementerio bajo una luna verde. Dorian toca el laúd dorado sobre un ataúd abierto mientras Cadence se arrodilla a su lado. En el ataúd yace una mujer de pelo rojo: Melody.",
	["cs.melody0.2"] = "Melody abre los ojos de golpe en un destello de luz morada.",
	["cs.melody0.3"] = "Se incorpora en el ataúd, y Cadence y Dorian sonríen.",
	["cs.melody0.4"] = "Una visión del NecroDancer derrotado, del que brota humo morado.",
	["cs.melody0.5"] = "En casa, Melody, con un pañuelo rojo y un vestido verde, toma una pala y el laúd dorado.",
	["cs.melody0.6"] = "Con una antorcha en alto, baja por un pozo de piedra hacia la cripta mientras unos tentáculos verdes salen de las paredes.",
	["cs.melody1.1"] = "Una habitación de enfermo. Melody yace en la cama, pálida, con una rosa roja sobre la manta. Dorian, con su gorra verde, está sentado a su lado y le sostiene la mano.",
	["cs.melody1.2"] = "Primer plano: Dorian se inclina sobre ella, con los ojos entornados y duros, mientras ella yace débil con la cabeza vendada.",
	["cs.melody2.1"] = "En la cocina de una casita de campo, una mujer de pelo gris con un laúd dorado, Aria, levanta con suavidad la barbilla de la joven Melody.",
	["cs.melody2.2"] = "Más tarde, la oscura silueta de Aria sale por la puerta, mientras Melody está de espaldas con la cabeza gacha.",
	["cs.melody3.1"] = "Un pueblo al anochecer. Aria toca su laúd dorado junto a la cama de un hombre enfermo mientras la joven Melody lo cuida.",
	["cs.melody3.2"] = "Un aldeano con una antorcha grita y señala a Aria en una puerta; otros se reúnen con horcas y guadañas.",
	["cs.melody3.3"] = "Melody y Aria están juntas con el laúd, rodeadas por las horcas de la turba, en un estallido de luz morada.",
	["cs.melody4.1"] = "En la sala de la cripta, Melody toca el laúd dorado sobre el NecroDancer, que yace en el suelo con su capa roja.",
	["cs.melody4.2"] = "Se levanta despacio: piel azul, ojos rojos, manos con garras que se extienden.",
	["cs.melody4.3"] = "Desde arriba: Melody sigue tocando mientras el NecroDancer se arrastra hacia ella.",
	["cs.melody4.4"] = "Primer plano del rostro del NecroDancer, que gruñe con los ojos de un rojo brillante.",
	["cs.melody4.5"] = "Primer plano: Melody rasguea el laúd con calma y no se detiene.",
	["cs.melody4.6"] = "El NecroDancer se yergue y grita de rabia en un estallido de luz morada.",
	["cs.melody5.1"] = "El NecroDancer retrocede tambaleándose hacia un ataúd de piedra abierto.",
	["cs.melody5.2"] = "Un destello de luz morada: una mujer de pelo gris con un vestido morado le clava una daga por la espalda mientras Melody mira.",
	["cs.melody5.3"] = "Su capa roja cae arrugada al suelo a los pies de la mujer.",
	["cs.melody5.4"] = "En la penumbra de la cripta, Melody se vuelve hacia la mujer de pelo gris, que aún sostiene la daga.",
	["cs.nocturna1.1"] = "Una cripta llena de máquinas extrañas. Nocturna, una vampira de piel azul pálido, pelo rojo y alas de murciélago, sostiene en alto una antorcha junto a una calavera gigante.",
	["cs.nocturna1.2"] = "Un esqueleto yace desplomado contra tuberías y manómetros mientras una chispa recorre un cable.",
	["cs.nocturna1.3"] = "Desde abajo: Nocturna se alza imponente con la antorcha y las alas desplegadas.",
	["cs.nocturna1.4"] = "Baja volando por una escalera oscura, con la antorcha por delante.",
	["cs.nocturna2.1"] = "Nocturna sostiene en alto una antorcha en una sala de máquinas y diales luminosos, y alarga la mano hacia la pared.",
	["cs.nocturna2.2"] = "Recorre un largo pasillo metálico lleno de cables y luces.",
	["cs.nocturna2.3"] = "Primer plano: su mano azul toca gruesos cables que chisporrotean con electricidad amarilla.",
	["cs.nocturna2.4"] = "Desde arriba: sigue los cables luminosos por el suelo.",
	["cs.nocturna2.5"] = "Sigue volando, con las alas desplegadas, por un túnel iluminado por el fuego.",
	["cs.nocturna3.1"] = "Un esqueleto con casco, conectado a las máquinas, está sentado y desplomado entre chispas amarillas.",
	["cs.nocturna3.2"] = "Primer plano: Nocturna lo examina, nada impresionada.",
	["cs.nocturna3.3"] = "Se agacha junto al esqueleto y tira de los cables de su espalda.",
	["cs.nocturna3.4"] = "Sostiene el manojo de cables con ambas manos y luego aprieta los puños.",
	["cs.nocturna3.5"] = "Se marcha sola por un largo pasillo; otro esqueleto conectado cuelga de la pared.",
	["cs.nocturna4.1"] = "Un recuerdo: una joven de piel morena y pelo castaño rizado grita y extiende la mano mientras un vampiro azul de ojos rojos le muerde el cuello, con una iglesia detrás bajo un cielo morado.",
	["cs.nocturna4.2"] = "Su piel se vuelve azul pálido y su pelo rojo mientras arde un fuego detrás de ella.",
	["cs.nocturna4.3"] = "En un bosque de abedules blancos, la alada Nocturna se agacha sobre un animal caído mientras unos ojos rojos la observan desde la oscuridad.",
	["cs.nocturna4.4"] = "Un vampiro alto de larga melena roja ondeante sale arrastrándose de la oscuridad hacia ella.",
	["cs.nocturna4.5"] = "Primer plano: Nocturna se mira las manos ensangrentadas y luego las cierra en puños.",
	["cs.nocturna5.1"] = "Un laboratorio de máquinas. Un enorme cuerpo mecánico morado yace sobre una mesa, con el pecho brillando mientras saltan chispas.",
	["cs.nocturna5.2"] = "Nocturna, con una espada en la mano, avanza hacia él.",
	["cs.nocturna5.3"] = "Una mujer con abrigo morado y gafas de latón, de pelo rubio alborotado y labios azules, se aparta de su trabajo: la Directora.",
	["cs.nocturna5.4"] = "Nocturna la apunta con su espada a través del vapor.",
	["cs.nocturna5.5"] = "La Directora se cruza de brazos, nada impresionada.",
	["cs.nocturna5.6"] = "Mira a Nocturna desde arriba con una sonrisa astuta.",
	["cs.nocturna5.7"] = "Se acerca a una máquina y saca un laúd dorado.",
	["cs.nocturna5.8"] = "El laúd resplandece con una luz amarilla en sus manos.",
	["cs.nocturna5.9"] = "Nocturna alza su espada.",
	["cs.nocturna5.10"] = "Nocturna se abalanza sobre ella mientras brotan rayos del laúd.",
	["cs.nocturna6.1"] = "Nocturna está de pie junto a la máquina destrozada de la Directora, entre el humo, espada en mano.",
	["cs.nocturna6.2"] = "Se mira la mano abierta.",
	["cs.nocturna6.3"] = "Una energía roja gira a su alrededor. Sus ojos brillan en rojo y sonríe enseñando los colmillos.",
	["cs.nocturna6.4"] = "Agarra un artefacto dorado que chisporrotea de rayos, lo alza con un grito y lo estrella contra un espejo.",
	["cs.nocturna6.5"] = "Agarra el laúd dorado y lo levanta sobre la cabeza, con los ojos ardiendo.",
	["cs.nocturna6.6"] = "Sus ojos vuelven a la normalidad. Duda.",
	["cs.nocturna6.7"] = "En el espejo agrietado ve a su yo humano: una mujer de piel morena, pelo castaño rizado y gafas redondas.",
	["cs.nocturna6.8"] = "Baja el laúd y lo sostiene con calma; ahora sus ojos son dorados.",
	["cs.nocturna6.9"] = "La luz cae por un pozo desde arriba. Su silueta asciende hacia ella y desaparece.",
	["cs.introDlc.1"] = "Noche en un cementerio bajo una luna llena y un cielo morado. Una rata de ojos rosas brillantes avanza sigilosa por una rama.",
	["cs.introDlc.2"] = "Las hojas vuelan sobre las tumbas.",
	["cs.introDlc.3"] = "Una mano oscura con garras surge de la tierra frente a una tumba, mientras una figura de ojos rojos se posa encima.",
	["cs.introDlc.4"] = "Una figura encapuchada de ojos rojos brillantes se alza en la oscuridad.",
	["cs.introDlc.5"] = "Primer plano: ojos rojos de vampiro y una sonrisa astuta.",
	["cs.introDlc.6"] = "Una silueta alada aterriza junto a una vieja tumba de piedra.",
	["cs.introDlc.7"] = "Nocturna está de pie bajo la luna llena, con las manos en las caderas y las alas de murciélago desplegadas.",
	["cs.introDlc.8"] = "Da un pisotón y la losa de piedra de la tumba se hace añicos.",
	["cs.introDlc.9"] = "Se asoma a la tumba rota, donde un pasaje de un rosa brillante lleva hacia abajo.",
	["cs.introDlc.10"] = "Se lanza dentro, y unas manos muertas salen arañando la tierra tras ella.",
	["cs.aria0.1"] = "En la cripta, Melody toca el laúd dorado. Detrás de ella está su madre Aria: pelo gris, vestido morado, armadura de cuero marrón y una daga en la mano.",
	["cs.aria0.2"] = "Primer plano: Melody la fulmina con la mirada, enfadada.",
	["cs.aria0.3"] = "Aria baja la mirada, avergonzada, a la luz de las antorchas.",
	["cs.aria0.4"] = "La ira de Melody se convierte en tristeza; sigue tocando.",
	["cs.aria0.5"] = "Aria tiende la mano abierta a su hija.",
	["cs.aria1.1"] = "Aria toca el laúd dorado ante un arco de piedra y calaveras.",
	["cs.aria1.2"] = "En un santuario oscuro y cubierto de maleza, alza el laúd junto a un pedestal de piedra donde arde una llama rosa.",
	["cs.aria1.3"] = "El laúd cobra vida en sus manos: su mástil se enrosca como un dragón dorado y le salen garras, mientras la llama rosa se aviva.",
	["cs.aria2.1"] = "Una taberna. Un joven bardo de barba roja y camisa azul toca un laúd en un pequeño escenario, mientras los bebedores lo ignoran.",
	["cs.aria2.2"] = "Más tarde, en un bosque oscuro, el mismo bardo, con una mochila y un bastón, se protege los ojos de un laúd dorado que brilla sobre una piedra.",
	["cs.aria3.1"] = "El bardo, Octavian, toca el laúd dorado para un ejército de monstruos: un enorme minotauro rojo de cuernos dorados, un limo verde lleno de huesos y esqueletos que agitan espadas.",
	["cs.aria3.2"] = "Mucho antes, Aria recorre la cripta vacía con una pala y una antorcha.",
	["cs.aria3.3"] = "Primer plano: Octavian, ahora no muerto y de piel azul, con una larga barba blanca y una capa roja, toca el laúd con ojos cansados y vacíos.",
	["cs.aria3.4"] = "El laúd se le escapa de las manos y se desvanece en la oscuridad.",
	["cs.aria4.1"] = "Aria, con una pala al lado, toca el laúd dorado sobre un ataúd de piedra abierto donde yace el NecroDancer.",
	["cs.aria4.2"] = "Unas manos azules se aferran al borde del ataúd cuando despierta.",
	["cs.aria4.3"] = "El NecroDancer se levanta y alarga la mano hacia el laúd mientras Aria sigue tocando.",
	["cs.aria4.4"] = "En un estallido de luz morada, Aria le tiende el laúd y sus manos azules se cierran sobre él.",
	["cs.aria4.5"] = "Él arrebata el laúd y aparta a Aria de un golpe, con los ojos brillando en rojo.",
	["cs.aria5.1"] = "En el santuario cubierto de maleza, Aria se protege los ojos mientras rayos morados brotan del pedestal alrededor del laúd dorado.",
	["cs.aria5.2"] = "Estrella el laúd contra el pedestal y brotan haces de luz morada.",
	["cs.aria5.3"] = "Los rayos morados la envuelven y se desploma contra la piedra.",
	["cs.aria5.4"] = "Al atardecer, en lo alto de una colina, Cadence está ante una lápida con el nombre de Aria grabado.",
	["cs.aria5.5"] = "Melody y Dorian se unen a ella, del brazo, mientras se pone el sol.",
}
